export default function Apptt() {
  return (
    <>
      {/* CSS داخل نفس الملف */}
      <style>
        {`
          .cards-container {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 25px;
            padding: 50px;
            justify-items: center;
          }

          .card {
            width: 250px;
            height: 150px;
            background: #ff7676;
            border-radius: 15px;
            color: white;
            display: flex;
            justify-content: center;
            align-items: center;
            position: relative;
            transition: all .5s ease;
            cursor: pointer;
          }

          .card:hover {
            width: 380px;
            height: 260px;
            background: #4c9aff;
          }

          .content {
            position: absolute;
            text-align: center;
            transition: .4s;
          }

          .normal {
            opacity: 1;
          }

          .hover {
            opacity: 0;
          }

          .card:hover .normal {
            opacity: 0;
          }

          .card:hover .hover {
            opacity: 1;
          }
        `}
      </style>

      {/* HTML */}
      <div className="cards-container">

        <div className="card">
          <div className="content normal">
            <h2>☀️</h2>
            <p>☀️ Summer in Oujda </p>
          </div>

          <div className="content hover">
            <h2>Div 1 Hover</h2>
            <p>تبدل المحتوى + الحجم 🎉</p>
          </div>
        </div>

        <div className="card">
          <div className="content normal">
            <h2> ❄️</h2>
            <p> ❄️ Winter in Oujda</p>
          </div>

          <div className="content hover">
            <h2>Div 2 Hover</h2>
            <p>تبدل المحتوى 🎉</p>
          </div>
        </div>

        <div className="card">
          <div className="content normal">
            <h2>🌧️</h2>
            <p> 🌧️ Rain in Oujda</p>
          </div>

          <div className="content hover">
            <h2>Div 3 Hover</h2>
            <p>💨 Wind in Oujda</p>
          </div>
        </div>

        <div className="card">
          <div className="content normal">
            <h2>Div 4</h2>
            <p>💨 Wind in Oujda</p>
          </div>

          <div className="content hover">
            <h2>Div 4 Hover</h2>
            <p>تبدل المحتوى 🎉</p>
          </div>
        </div>

      </div>
    </>
  );
}
